'use strict';
// Level 51–75 contracts belong exclusively to Faelar in the Elven Castle.
(() => {
  const XP_BASIS_POINTS=1800;
  function freeze(value){if(value&&typeof value==='object'){Object.values(value).forEach(freeze);Object.freeze(value);}return value;}
  const LOCATIONS=freeze([
    {id:'mirror-gardens',name:'Ogrody Rozbitego Zwierciadła',levels:[51,55],connection:'Zamek Elfów · Eldor',description:'Za Zamkiem Elfów w Eldorze rozciągają się dawne ogrody wróżbiarskie. Pęknięte sadzawki odbijają nieistniejące gwiazdy, a resztki ochronnej pieśni zmieniają drobne zwierzęta w niezwykłe istoty. To osobny teren poza dziedzińcem zamku.'},
    {id:'silent-archives',name:'Podzamcze Milczących Kronik',levels:[56,60],connection:'Podziemia Zamku Elfów · Eldor',description:'Niższe archiwa i cysterny pod elficką siedzibą zostały zalane wodą z uszkodzonych sadzawek. Rozpuszczony atrament przenosi resztki zaklęć między regałami. Dawna droga bibliotekarzy prowadzi stąd do górskiego traktu.'},
    {id:'ringing-pass',name:'Przesmyk Dzwoniących Traw',levels:[61,65],connection:'Trakt z Eldoru ku Lodowym Wzgórzom',description:'Pradawny szlak elfickich posłów i krasnoludzkich kupców biegnie przez wysokie siodło. Miedziane trawy dzwonią przed nadejściem burzy, a smukłe drogowskazy Eldoru ustępują tu kamiennym znakom krasnoludów.'},
    {id:'blind-aurora',name:'Moreny Ślepej Zorzy',levels:[66,70],connection:'Przedgórze Lodowych Wzgórz',description:'Na przedgórzu Lodowych Wzgórz zielona zorza odbija się w lodowych grzbietach i myli wędrowcom kierunki. W morenach leżą zatopione krasnoludzkie słupy graniczne. To otoczenie gór, a nie nowe wejście do zamku.'},
    {id:'ice-crown-basin',name:'Niecka Korony Lodu',levels:[71,75],connection:'Podnóże zamku krasnoludów · Lodowe Wzgórza',description:'Pod skalną koroną, na której wznosi się zamek krasnoludów, lodowiec wyrzeźbił wielki amfiteatr. Dawne morze pozostawiło w nim osobliwą faunę. Złote monolity łączą runy gór z pieśnią przyniesioną z Eldoru; dostęp do właściwych Lodowych Wzgórz nadal wymaga poziomu 75.'}
  ].map((place,tile)=>({...place,image:'eldor-locations.webp',columns:3,rows:2,tile})));
  const rows=[
    ['moon-silkmoth','Jedwabnik Księżycowej Rosy','silkmoth','caster','Jedwab, który pamięta gwiazdy','Wielka ćma rozwija srebrne skrzydła nad sadzawką i przędzie nici z resztek pieśni ochronnej. Ich blask zwabia ogrodników daleko od ścieżek.',{attackElement:'magic',special:{type:'magic-wave',every:4,damage:45,ability:'moon-silk'},traits:'Ataki magiczne; co czwarty własny atak dodaje falę 45 bazowych obrażeń magicznych.'}],
    ['pearl-frill','Wachlarznik Perłowy','frill-lizard','predator','Perły w rozbitym lustrze','Sześcionogi gad rozpościera kolisty perłowy kołnierz. Każda płytka odbija inny ruch przeciwnika, zanim zwierzę wykona gwałtowny skok.',{special:{type:'power',every:4,multiplier:135,ability:'pearl-lunge'},traits:'Co czwarty własny atak: skok zadaje 135% bazowych obrażeń.'}],
    ['sapphire-snail','Muszlowiec Szafirowy','land-snail','brute','Ślad pod szafirową kopułą','Wielki ślimak przenosi w przezroczystej muszli świetliste okruchy zwierciadeł. Śluz pożera zaprawę starych elfickich schodów.',{physicalArmor:14,magicVulnerability:20,traits:'Pochłania 14 obrażeń fizycznych. Otrzymuje 20% więcej obrażeń magicznych.'}],
    ['stained-glass-mimic','Mimik Żywego Witrażu','glass-mimic','caster','Okno, które zamknęło ogród','Kolorowe szkło opuściło ramę pałacowego okna i ułożyło się w drapieżny ruchomy wachlarz. Cienkie metalowe wąsy chwytają każdy cień pod arkadą.',{attackElement:'magic',physicalResistance:12,special:{type:'flat',every:3,bonus:45,ability:'glass-shear'},traits:'Magiczne ataki; odporność fizyczna 12%. Co trzeci własny atak dodaje 45 bazowych obrażeń.'}],
    ['crown-scarab','Skarabeusz Koronny','scarab','brute','Korona pod złotym pancerzem','Żuk wielkości wozu toczy między rabatami kule dawnego wosku pieczętnego. Turkusowe żyłki jego pancerza pulsują przy każdej fałszywej nucie pieśni Eldoru.',{armor:12,special:{type:'piercing',every:4,piercing:30,ability:'crown-mandibles'},traits:'Pancerz pochłania 12 obrażeń. Co czwarty własny atak ignoruje 30% redukcji pancerza i odporności fizycznej.'}],
    ['velvet-bookeater','Księgożer Aksamitny','pangolin','brute','Znikające marginesy','Łuskowiec obgryza grzbiety kronik. Jego ciemne łuski układają się jak zapisane karty, a długie pazury rozcinają skrzynie z pergaminem.',{physicalArmor:16,special:{type:'power',every:5,multiplier:140,ability:'folio-claws'},traits:'Pochłania 16 obrażeń fizycznych. Co piąty własny atak zadaje 140% bazowych obrażeń.'}],
    ['inkwell-octopus','Ośmiornica Atramentowych Studni','octopus','predator','Atrament ponad wodą','Osiem ramion wspina się po mokrych półkach bez jednego plusku. Zwierzę karmi się zaklętym atramentem i pozostawia nim gorzkie ślady na kamieniu.',{special:{type:'dot',every:4,damage:30,turns:3,label:'Żrący atrament',ability:'caustic-ink'},traits:'Co czwarty własny atak: żrący atrament zadaje 30 obrażeń na początku 3 kolejnych tur celu.'}],
    ['moon-cistern-axolotl','Aksolotl Księżycowych Cystern','axolotl','caster','Skrzela pod srebrną kratą','Biały płaz o rozgałęzionych fioletowych skrzelach strzeże wylotu cysterny. Jego oddech wzbudza na wodzie kręgi o kształcie elfickich liter.',{attackElement:'water',special:{type:'magic-wave',every:4,damage:50,ability:'cistern-pulse'},traits:'Atakuje wodą, omijając obronę fizyczną. Co czwarty własny atak dodaje falę 50 bazowych obrażeń magicznych.'}],
    ['tapestry-maw','Strzępnik Gobelinów','living-tapestry','predator','Gobelin, który zszedł ze ściany','Ciężka tkanina poluje na ciepło czytelników. Złote nici ściągają się w paszczę, a zrolowane narożniki służą jej za silne przednie kończyny.',{physicalResistance:15,magicVulnerability:25,special:{type:'flat',every:4,bonus:50,ability:'tapestry-bind'},traits:'Odporność fizyczna 15%; podatność na magię 25%. Co czwarty własny atak dodaje 50 bazowych obrażeń.'}],
    ['orbital-cartographer','Sferyczny Kartograf','living-orrery','caster','Mapa bez północy','Żywe planetarium odłączyło się od sklepienia biblioteki. Mosiężne pierścienie obracają się wokół błękitnego rdzenia i wyznaczają drogę do nieistniejącej gwiazdy.',{attackElement:'magic',armor:10,special:{type:'magic-wave',every:3,damage:50,ability:'orbital-convergence'},traits:'Magiczne ataki; pancerz pochłania 10 obrażeń. Co trzeci własny atak dodaje falę 50 bazowych obrażeń magicznych.'}],
    ['storm-ridge-manta','Płaszczka Grzbietu Burzy','flying-manta','caster','Cień pod chmurą','Płaszczka płynie nad trawami jak po wzburzonej wodzie. Elektryczne żyłki na jej skórzastych płetwach rozbłyskują, gdy wiatr dotyka drogowskazów Eldoru.',{attackElement:'magic',special:{type:'magic-wave',every:4,damage:60,ability:'storm-ridge'},traits:'Atakuje magicznym wyładowaniem. Co czwarty własny atak dodaje falę 60 bazowych obrażeń magicznych.'}],
    ['copper-grass-behemoth','Behemot Dzwoniących Traw','grassland-behemoth','brute','Dzwonienie nad przełęczą','Potężne kopyta ugniatają trakt dawnych poselstw. Miedziana sierść brzmi jak dzwonki, a dwa zakrzywione rogi rozbijają słupy graniczne.',{special:{type:'power',every:5,multiplier:145,ability:'copper-charge'},enrage:{threshold:30,bonus:15},traits:'Co piąty własny atak zadaje 145% bazowych obrażeń. Poniżej 30% HP bazowe obrażenia rosną o 15%.'}],
    ['white-crag-harpy','Harpia Białych Turni','harpy','predator','Głos ponad przepaścią','Ptasia twarz spogląda z jasnego klifu, zanim rozłożą się czarne skrzydła. Harpia gromadzi metalowe znaki kupców w gniazdach poza zasięgiem lin.',{special:{type:'piercing',every:3,piercing:35,ability:'crag-talons'},traits:'Co trzeci własny atak: szpony ignorują 35% redukcji pancerza i odporności fizycznej.'}],
    ['spire-webweaver','Tkacz Iglicowych Sieci','spider','predator','Struny między drogowskazami','Osiem długich nóg rozciąga sieć pomiędzy kamiennymi iglicami. Srebrny wzór na odwłoku przypomina harfę, lecz jej struny niosą jad.',{special:{type:'dot',every:4,damage:38,turns:3,label:'Jad tkacza',ability:'spire-venom'},traits:'Co czwarty własny atak: jad zadaje 38 obrażeń na początku 3 kolejnych tur celu.'}],
    ['three-voice-manticore','Mantykora Trzech Głosów','manticore','brute','Trzy głosy jednego gardła','Lwie ciało, nietoperze skrzydła i kolczasty ogon należą do jednej bestii. Jej trzy głosy naśladują zaginione poselstwa elfów i krasnoludów.',{special:{type:'piercing',every:4,piercing:40,ability:'threefold-sting'},enrage:{threshold:25,bonus:20},traits:'Co czwarty własny atak ignoruje 40% redukcji pancerza i odporności fizycznej. Poniżej 25% HP bazowe obrażenia rosną o 20%.'}],
    ['ice-mirror-owl','Puchacz Lodowych Luster','owl','predator','Oczy w martwym odbiciu','Olbrzymi puchacz obserwuje moreny z lodowego grzbietu. Jego biała tarcza twarzowa nie odbija się w zamarzniętych kałużach.',{special:{type:'power',every:4,multiplier:140,ability:'mirror-dive'},traits:'Co czwarty własny atak: pikowanie zadaje 140% bazowych obrażeń.'}],
    ['white-moraine-tardigrade','Niesporczak Białej Moreny','tardigrade','brute','Osiem pazurów pod lodem','Ośmionogi niesporczak wyrósł w wodzie wypływającej spod runicznych kamieni. Przez mleczne segmenty widać powolny ruch błękitnego światła.',{armor:18,magicVulnerability:20,traits:'Pancerz pochłania 18 obrażeń. Otrzymuje 20% więcej obrażeń magicznych.'}],
    ['tripod-echo-oyster','Ostrygowiec Zimnego Echa','tripod-oyster','caster','Perła, która odpowiada','Dwie czarne muszle unoszą się na trzech mięsistych stopach. Perła w ich wnętrzu oddaje każde zawołanie falą zimnego światła.',{physicalArmor:20,attackElement:'water',special:{type:'magic-wave',every:4,damage:65,ability:'pearl-echo'},traits:'Pochłania 20 obrażeń fizycznych i atakuje wodą. Co czwarty własny atak dodaje falę 65 bazowych obrażeń magicznych.'}],
    ['aurora-jellyfish','Meduza Ślepej Zorzy','jellyfish','caster','Zorza, która opada','Przezroczysty dzwon dryfuje pomiędzy lodowymi kolumnami. Zielone czułki zbierają światło zorzy i pozostawiają na skórze długotrwałe pieczenie.',{attackElement:'magic',physicalResistance:15,special:{type:'dot',every:4,damage:42,turns:3,label:'Parzydełka zorzy',ability:'aurora-sting'},traits:'Magiczne ataki; odporność fizyczna 15%. Co czwarty własny atak: parzydełka zadają 42 obrażenia przez 3 tury celu.'}],
    ['runic-ice-crab','Krab Runicznych Szczelin','ice-crab','brute','Szczypce pod znakiem granicy','Szeroki skorupiak rozłupuje szczeliny pod krasnoludzkimi słupami. Jedna szczypca kruszy lód, a druga chwyta znaki wyrwane z kamienia.',{physicalArmor:24,special:{type:'power',every:5,multiplier:145,ability:'runic-clamp'},traits:'Pochłania 24 obrażenia fizyczne. Co piąty własny atak zadaje 145% bazowych obrażeń.'}],
    ['glacier-ribbonworm','Wstężnica Lodowego Dna','ribbon-flatworm','predator','Wstęga pod śniegiem','Szerokie, płaskie ciało przesuwa się fałdami po dnie niecki. Falujące brzegi odcinają drogę odwrotu, zanim mała strzałkowata głowa dosięgnie celu.',{special:{type:'dot',every:4,damage:45,turns:3,label:'Śluz wstężnicy',ability:'glacier-mucus'},traits:'Co czwarty własny atak: śluz zadaje 45 obrażeń na początku 3 kolejnych tur celu.'}],
    ['deep-frost-coral','Koralnik Głębokiego Mrozu','walking-coral','brute','Morze zapisane w lodzie','Czerwonoczarna korona koralowa wędruje na sześciu kościstych podporach. To pozostałość dawnego morza, przebudzona przez odwrócone runy.',{physicalArmor:22,magicVulnerability:20,special:{type:'flat',every:4,bonus:65,ability:'coral-splinters'},traits:'Pochłania 22 obrażenia fizyczne; podatność na magię 20%. Co czwarty własny atak dodaje 65 bazowych obrażeń.'}],
    ['night-basin-narwhal','Narwal Nocnej Niecki','floating-narwhal','caster','Róg ponad dawnym morzem','Blady blask prowadzi po lodzie wielkie wielorybie ciało. Spiralny kieł przecina mgłę, w której rozbrzmiewa ostatnia zwrotka pieśni Eldoru.',{attackElement:'water',special:{type:'piercing',every:4,piercing:40,ability:'night-tusk'},traits:'Atakuje wodą. Co czwarty własny atak ignoruje 40% redukcji pancerza i odporności fizycznej.'}],
    ['glacial-crown-starfish','Rozgwiazda Zamarłego Kręgu','starfish','brute','Pięć ramion na kamieniu','Pięć płytowych ramion przylega do monolitu jak żywy znak. Bursztynowa paszcza w środku ciała budzi się po każdym poruszeniu złotej runy.',{armor:20,special:{type:'magic-wave',every:4,damage:75,ability:'frozen-circle'},traits:'Pancerz pochłania 20 obrażeń. Co czwarty własny atak dodaje falę 75 bazowych obrażeń magicznych.'}],
    ['ice-crown-mammoth','Mamut Korony Lodu','four-tusk-mammoth','brute','Cztery kły pod koroną','Czterokły mamut pamięta zimy sprzed budowy obu zamków. Zamarznięta sierść dźwiga okruchy dawnych drogowskazów, a jego ryk odbija się od całego amfiteatru.',{physicalArmor:25,special:{type:'power',every:5,multiplier:150,ability:'ice-crown-charge'},enrage:{threshold:25,bonus:15},traits:'Pochłania 25 obrażeń fizycznych. Co piąty własny atak zadaje 150% bazowych obrażeń; poniżej 25% HP bazowe obrażenia rosną o 15%.'}]
  ];
  function threshold(level){const need=Number.isSafeInteger(level)&&level>0?window.Progression.required(level):null;if(!Number.isSafeInteger(need)||need<=0)throw Error('Brak progu EXP dla tego poziomu.');return need;}
  const MONSTERS=freeze(rows.map(([id,name,species,kind,contractTitle,description,rules],index)=>{
    const level=51+index,place=LOCATIONS[Math.floor(index/5)],maxHp=2700+140*index+3*index*index+(kind==='brute'?200:kind==='caster'?-120:-50),power=Math.round(level*3),secondary=Math.round(level*1.5),attackMin=300+12*index;
    return{id,name,species,kind,level,sceneId:place.id,contractTitle,description,maxHp,stats:kind==='caster'?[level,secondary,power,Math.round(maxHp/10)]:kind==='predator'?[Math.round(level*2.5),power,level,Math.round(maxHp/10)]:[power,secondary,level,Math.round(maxHp/10)],attack:[attackMin,attackMin+38+index],...rules,rewardVersion:1,reward:{xp:Math.floor(threshold(level)*XP_BASIS_POINTS/10000),gold:850+70*index+40*Math.floor(index/5)},image:`eldor-monsters-${place.id}.webp`,columns:3,rows:2,tile:index%5};
  }));
  function get(id){const enemy=MONSTERS.find(enemy=>enemy.id===id);if(!enemy)throw Error('Nieznany potwór szlaku Eldoru.');return enemy;}
  function rewardFor(id,playerLevel=get(id).level){const enemy=get(id);return{gold:enemy.reward.gold,xp:Math.floor(Math.min(threshold(playerLevel),threshold(enemy.level))*XP_BASIS_POINTS/10000)};}
  window.EldorBestiary=freeze({VERSION:1,STATUS:'available-at-faelar',MISSION_POOL_ENABLED:true,MIN_LEVEL:51,MAX_LEVEL:75,XP_BASIS_POINTS,LOCATIONS,MONSTERS,get,rewardFor,atLevel:level=>MONSTERS.find(enemy=>enemy.level===level)??null});
})();
